package com.yeyamo_mobile.api.auth_service.event;
import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.auth_service.models.User;
@Component public class AuthEventOutbox{private final AuthOutboxRepository repo;private final ObjectMapper mapper;public AuthEventOutbox(AuthOutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void userCreated(User user,String correlationId){Map<String,Object>p=new LinkedHashMap<>();p.put("userId",String.valueOf(user.getId()));p.put("email",user.getEmail());p.put("phone",user.getPhone());p.put("status",user.getStatus().name());append("user.created",String.valueOf(user.getId()),String.valueOf(user.getId()),correlationId,p);}public void roleAdded(User user,String role,String correlationId){append("user.role_added",String.valueOf(user.getId()),"partner-service",correlationId,Map.of("userId",String.valueOf(user.getId()),"role",role));}private void append(String type,String aggregate,String actor,String correlation,Map<String,Object>payload){try{UUID id=UUID.randomUUID();Instant now=Instant.now();Map<String,Object>e=new LinkedHashMap<>();e.put("eventId",id);e.put("eventType",type);e.put("eventVersion",1);e.put("occurredAt",now);e.put("producer","auth-service");e.put("correlationId",correlation);e.put("actorId",actor);e.put("payload",payload);AuthOutboxEvent row=new AuthOutboxEvent();row.setId(id);row.setAggregateId(aggregate);row.setEventType(type);row.setPayload(mapper.writeValueAsString(e));row.setOccurredAt(now);repo.save(row);}catch(Exception x){throw new IllegalStateException("Unable to create auth event",x);}}}
